ize:9px;gap:15px;flex-wrap:wrap}.hero-art{width:100%;max-width:460px;height:350px}.monitor{top:20px}.game{height:235px}.game-text{top:68px}.game-text h2{font-size:29px}.halo{width:290px;height:290px;left:20px}.launcher{width:195px;right:0}.launcher-symbol{height:74px;font-size:56px}.stand{top:296px}.float-tag{font-size:6px;padding:10px;bottom:22px}.caption{display:none}.compat{justify-content:center;flex-wrap:wrap;gap:17px;padding-top:20px;padding-bottom:20px}.compat small:first-child{width:100%;text-align:center}.compat b{font-size:17px}section{padding-top:52px;padding-bottom:52px}.section-head{display:block}h2{font-size:29px}.section-head p{font-size:11px}.services{gap:12px}.service{padding:18px 14px}.service h3{font-size:16px;min-height:38px}.service p{min-height:58px}.service ul{font-size:9px;line-height:2}.service button{font-size:9px}.tech{display:block}.tech h2{font-size:29px}.tech-grid{margin-top:30px;gap:22px}.projects,.plans{grid-template-columns:1fr}.project-visual{height:230px;padding:25px 35px}.mini-window{height:182px}.mini-body{height:167px}.mini-body h4{font-size:29px;max-width:170px}.plans{gap:28px}.plan{padding:28px}.plan p{min-height:0}.contact h2{font-size:35px}.contact p{font-size:12px}footer{flex-wrap:wrap;gap:16px}footer small{margin-left:0;flex:1;font-size:8px}footer button{width:100%;text-align:left}.panel{display:block}.sidebar{flex-direction:row;overflow:auto;border-right:0;padding:0;margin-bottom:22px}.sidebar button{white-space:nowrap}.metrics{gap:7px}.metric{padding:12px}.metric small{font-size:8px}.metric b{font-size:21px}#content{padding:20px}.form-grid{grid-template-columns:1fr}.full{grid-column:auto}.demo-stage{padding:25px}.demo-stage h3{font-size:35px}.demo-stat{gap:12px;font-size:9px}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important}}

